const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  var quebec = ee.FeatureCollection("FAO/GAUL/2015/level1")
    .filter(ee.Filter.eq('ADM1_NAME', 'Quebec'));

  var startDate = '2023-01-01';
  var endDate = '2023-12-31';

  // 2. Data Acquisition - MODIS Burned Area product
  var burnedArea = ee.ImageCollection('MODIS/061/MCD64A1')
    .filterDate(startDate, endDate)
    .filterBounds(quebec);

  var burnedAreaSize = burnedArea.size().getInfo();
  print('2023 MODIS Burned Area Images:', burnedAreaSize);

  if (burnedAreaSize === 0) {
    print("No burned area data found for 2023.");
    print("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Create burned area mask and calculate area
  var burnedMask = burnedArea.select('BurnDate').max().gt(0);

  // Calculate area per pixel (500m resolution = 25 hectares per pixel)
  var areaImage = burnedMask.multiply(ee.Image.pixelArea()).divide(10000); // Convert m² to hectares

  // 4. Calculation - Sum burned area over Quebec
  var burnedStats = areaImage.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: quebec,
    scale: 500,
    maxPixels: 1e9
  });

  var totalBurnedArea = burnedStats.get('BurnDate').getInfo();

  // Check for valid pixels
  var pixelCount = burnedMask.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: quebec,
    scale: 500,
    maxPixels: 1e9
  }).get('BurnDate').getInfo();

  print('Burned pixels count:', pixelCount);

  if (pixelCount === 0) {
    print("No burned pixels detected in Quebec for 2023.");
    print("<answer>C2</answer>");
    return;
  }

  // 5. Validation & Final Answer
  if (totalBurnedArea === null || totalBurnedArea === undefined || 
      isNaN(totalBurnedArea) || totalBurnedArea < 0) {
    print("Invalid area calculation:", totalBurnedArea);
    print("<answer>C3</answer>");
    return;
  }

  print('Total burned area (hectares):', Math.round(totalBurnedArea));

  if (totalBurnedArea > 160000) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
